#include <stdio.h>

int main() {
    int n;
    int max_venta = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int venta;
        scanf("%d", &venta);
        if (venta > max_venta) {
            max_venta = venta;
        }
    }
    printf("%.1f\n", max_venta);
    return 0;
}

#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    int ventas[100];
    int count = 0;
    for (int i = 0; i < n; i++) {
        int venta;
        scanf("%d", &venta);
        ventas[count] = venta;
        count++;
    }
    for (int i = 0; i < count; i++) {
        printf("%d ", ventas[i]);
    }
    return 0;
}
